            { id = 4460, step = 4, speaker = 8480, delay = 25, chat = "say", male = "SILENCE FOOL!" },
            { id = 4461, step = 5, speaker = 8480, delay = 31, chat = "say", male = "They will live, if only to see the fruits of their labor: the destruction and chaos that will surely ensue as the legion of Blackrock invade the gorge." },
            { id = 4462, step = 6, speaker = 8480, delay = 38, chat = "say", male = "I leave you now, mortals. Alive and with these trinkets. Maltrake! Present them with the trinkets!" },
            { id = 4468, step = 7, speaker = 8509, delay = 38, chat = "say", male = "Right away, master!" },
            { id = 4463, step = 8, speaker = 8480, delay = 47, chat = "say", male = "Oh yes, the molt - do not lose it. There are those of my kin in the Burning Steppes that would craft items that only the molt of the black Dragonflight could fortify." },
            { id = 4465, step = 9, speaker = 8480, delay = 54, chat = "yell", male = "The legion of Blackrock comes, dwarflings! We shall scorch the earth and set fire to the heavens. None shall survive..." },
        },
