        [3906] = { -- Disharmony of Flame
            { id = 4717, step = 1, speaker = 9078, delay = 1, chat = "whisper", male = "You are indeed powerful, $n. Come to me if it is more work that you seek." },
            { id = 4718, step = 2, speaker = 9081, delay = 4, chat = "whisper", male = "My eyes never deceive me, $r. I see great power in you - enough power, perhaps, to further our cause. Find me at the top of the tower." },
        },
        [3908] = { -- It's a Secret to Everybody
            { id = 6153, step = 1, speaker = 9298, delay = 1, chat = "say", male = "Please, follow me." },
            { id = 6154, step = 2, speaker = 9298, delay = 15, chat = "say", male = "I haven't really figured out what it is, but there's something strange about the hot springs..." },
            { id = 6156, step = 3, speaker = 9298, delay = 26, chat = "say", male = "I've found that when I throw something into this water, it has improved incredibly when I retrieve it." },
            { id = 6157, step = 4, speaker = 9298, delay = 30, chat = "say", male = "Well, whatever it is, it works quite well!" },
            { id = 6158, step = 5, speaker = 9298, delay = 48, chat = "say", male = "And I am determined to find out more... So if you need my help again, you know where I'll be." },
        },
        [3922] = { -- Nugget Slugs
