        [3941] = { -- A Gnome's Assistance
            { id = 4839, step = 1, speaker = 9117, delay = 7, chat = "say", male = "I know it'll work this time..." },
            { id = 4840, step = 1, speaker = 9117, delay = 7, chat = "say", male = "This will be my best experiment yet!" },
            { id = 4841, step = 1, speaker = 9117, delay = 7, chat = "say", male = "Now, if I add the yellow ones..." },
            { id = 4842, step = 1, speaker = 9117, delay = 7, chat = "say", male = "I know it'll work this time... My last 13 tries were just practice!" },
            { id = 4847, step = 2, speaker = 9117, delay = 16, chat = "say", male = "I think... I think it's working!" },
            { id = 4852, step = 3, speaker = 9117, delay = 20, chat = "say", male = "OW! That's not right!" },
            { id = 4853, step = 4, speaker = 9117, delay = 23, chat = "say", male = "Oh well... Maybe next time." },
        },
        [4129] = { -- The Knife Revealed
            { id = 5148, step = 1, speaker = 7879, delay = 2, chat = "say", male = "I will need to focus my energies onto this knife.  By doing so, I should catch some of the stronger psychic impressions associated with it." },
