        [7496] = { -- Celebrating Good Times
            { id = 9495, step = 1, speaker = 14394, delay = 3, chat = "yell", male = "Citizens and allies of Stormwind, on this day, history has been made. $n has laid waste to that which had attempted to usurp the rule of the kingdom. Gather round and join me in honoring our heroes." },
