        [8984] = { -- The Source Revealed
            { id = 11838, step = 1, speaker = 16110, delay = 2, chat = "say", male = "Staffron..." },
            { id = 11836, step = 2, speaker = 16107, delay = 4, chat = "say", male = "Annalise? Is that you?" },
            { id = 11837, step = 3, speaker = 16110, delay = 8, chat = "say", male = "My dear Staffron, have you forgotten what it is to love? The love that we once shared?" },
            { id = 11839, step = 4, speaker = 16107, delay = 14, chat = "say", male = "Have I forgotten? Of course I have... I have forgotten about love, happiness... of life itself." },
            { id = 11840, step = 5, speaker = 16107, delay = 21, chat = "say", male = "But I do know this - love makes the heart and body weak. It can be exploited. Without your love, I have only my work, Annalise." },
            { id = 11841, step = 6, speaker = 16110, delay = 29, chat = "say", male = "But of course I love you, Staffron. And it pains me to see you suffer so." },
            { id = 11842, step = 7, speaker = 16110, delay = 36, chat = "say", male = "I pledge my love to you forever. Death cannot erase that, even as I am sure that you still remember your love for me." },
            { id = 11843, step = 8, speaker = 16110, delay = 43, chat = "say", male = "And if you do not, then I am truly lost." },
            { id = 11844, step = 9, speaker = 16107, delay = 48, chat = "say", male = "How could you love me, Annalise? Look at me. I am not the man you once knew." },
            { id = 11845, step = 10, speaker = 16107, delay = 56, chat = "say", male = "Annalise? Annalise! No, don't leave me!" },
            { id = 11846, step = 11, speaker = 16107, delay = 62, chat = "say", male = "Annalise... You're right. I-I can't do this. I must find another way." },
            { id = 11847, step = 12, speaker = 16107, delay = 68, chat = "say", male = "You there. You're welcome to take the contents of my cauldron. It was to be the second stage of my plan - amorous clothing." },
        },
