            { id = 1831, step = 1, speaker = 5386, delay = 1, chat = "say", male = "I'm lucky to be alive!" },
        },
        [1476] = { -- Hearts of the Pure
            { id = 1988, step = 1, speaker = 5693, delay = 3, chat = "say", male = "This is Dalin Forgewright. He fled from Lordaeron when the plague struck, taking his love with him." },
            { id = 1992, step = 2, speaker = 5693, delay = 8, chat = "say", male = "When he came upon the refugees at the Greymane Wall, he felt it his duty to succor them, sending his woman on to Hillsbrad." },
            { id = 1989, step = 3, speaker = 5693, delay = 15, chat = "say", male = "And this is Comar Villard. Two weeks married, his wife was spirited away from the safety of Menethil Harbor." },
            { id = 1993, step = 4, speaker = 5693, delay = 19, chat = "say", male = "Five and five years, and he still searches for her, though she was no beauty, and there were many ladies that would take her place." },
            { id = 1990, step = 5, speaker = 5693, delay = 22, chat = "say", male = "Fools." },
        },
        [1680] = { -- Tormus Deepforge
            { id = 2302, step = 1, speaker = 6114, delay = 0, chat = "say", male = "Farewell, $n.  And remember, a warrior never shows his back to his foe!" },
