        [1738] = { -- Heartswood
            { id = 2310, step = 1, speaker = 6244, delay = 1, chat = "say", male = "A thousand years ago, the immortal elves, demigods of the forest and dragons fought against the Legion on the slopes of Hyjal." },
            { id = 2311, step = 2, speaker = 6244, delay = 8, chat = "say", male = "Anathera and Latherion fought back to back where the battle was thickest. Two lovers determined to survive the war together." },
            { id = 2312, step = 3, speaker = 6244, delay = 12, chat = "say", male = "But it was not to be. As their foes pressed close, Anathera's armor was pierced by a demon's tainted blade. In the thick of battle, there would be nothing to save her." },
            { id = 2313, step = 4, speaker = 6246, delay = 15, chat = "say", male = "Anathera!" },
            { id = 2314, step = 5, speaker = 6244, delay = 20, chat = "say", male = "Ignoring the battle that raged about him, Latherion dropped his guard to cradle his love in her dying moments. But the demons gave him no quarter, and quickly laid him low." },
            { id = 2315, step = 6, speaker = 6246, delay = 24, chat = "say", male = "Anathera... I cannot bear to face the rest of eternity without you by my side... If you are taken from me, then let this be the day I also return to the earth..." },
            { id = 2316, step = 7, speaker = 6245, delay = 26, chat = "say", male = "So this... this is how it ends, my love..." },
            { id = 2317, step = 8, speaker = 6244, delay = 30, chat = "say", male = "Where the two lovers fell, a tree would bloom. The elves call it the heartswood. It will surely serve your ends." },
        },
        [1784] = { -- The Tome of Divinity
            { id = 2351, step = 1, speaker = 6177, delay = 0, chat = "say", male = "Good luck, $n. And remember, find Muiredon once you've accomplished the task." },
