        [2460] = { -- The Shattered Salute
            { id = 3278, step = 1, speaker = 3401, delay = 1, chat = "say", male = "$n, pay very close attention to what I do and follow my instructions precisely. To not heed my words is to sign your own death warrant, as Taskmaster Fizzule is VERY well versed in the ways of the warrior and the assassin." },
            { id = 3279, step = 2, speaker = 3401, delay = 8, chat = "say", male = "After you get his attention - and you can be certain that if he sees you near the tower, you'll have his undue attention - face him and perform the Shattered /Salute. Let me demonstrate...." },
            { id = 3281, step = 3, speaker = 3401, delay = 25, chat = "say", male = "Did you see what I did? If you are unsure of the technique used in presenting the /salute, practice on me. If you correctly execute the Shattered /Salute, I will give you the proper response." },
